def pretty_print_diff(diff):
    if 'old_type' in diff and 'new_type' in diff:
        old_type = diff['old_type']
        new_type = diff['new_type']
        old_value = diff['old_value']
        new_value = diff['new_value']
        return f"Type of {diff['key']} changed from {old_type} to {new_type}. {old_type}: {old_value} --> {new_type}: {new_value}"
    elif 'old_value' in diff and 'new_value' in diff:
        old_value = diff['old_value']
        new_value = diff['new_value']
        return f"Value of {diff['key']} changed from {old_value} to {new_value}"
